// Package main wires all sensor-service layers together and starts the HTTP server.
// Pre-requisites: run `buf generate` in sensor-service/ to produce api/v1/*.pb.go
package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"connectrpc.com/connect"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.uber.org/zap"

	"p9e.in/samavaya/packages/connect/interceptors"
	connectserver "p9e.in/samavaya/packages/connect/server"
	"p9e.in/samavaya/packages/deps"
	"p9e.in/samavaya/packages/p9log"

	// Generated by buf generate — run `buf generate` in sensor-service/ first.
	sensorv1connect "p9e.in/samavaya/agriculture/sensor-service/api/v1/sensorv1connect"

	grpcadapter "p9e.in/samavaya/agriculture/sensor-service/internal/adapters/inbound/grpc"
	"p9e.in/samavaya/agriculture/sensor-service/internal/repositories"
	"p9e.in/samavaya/agriculture/sensor-service/internal/services"
)

func main() {
	zapLogger, err := zap.NewProduction()
	if err != nil {
		log.Fatalf("failed to create logger: %v", err)
	}
	defer zapLogger.Sync() //nolint:errcheck
	logger := p9log.NewLogger(zapLogger)

	dsn := envOr("DATABASE_URL", "postgres://localhost:5432/sensor_service?sslmode=disable")
	port := envOr("PORT", "8080")

	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()

	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		log.Fatalf("failed to connect to database: %v", err)
	}
	defer pool.Close()

	if err := pool.Ping(ctx); err != nil {
		log.Fatalf("database ping failed: %v", err)
	}

	// Build ServiceDeps with the available infrastructure
	serviceDeps := deps.ServiceDeps{
		Pool: pool,
		Log:  logger,
	}

	// Outbound adapters — rich repository backed by full SQL
	repo := repositories.NewSensorRepository(pool, logger)

	// Application service — rich service with domain logic
	svc := services.NewSensorService(repo, serviceDeps)

	// Inbound adapters
	handler := grpcadapter.NewSensorHandler(svc, logger)

	mwCfg := connectserver.MiddlewareConfig{
		EnableRecovery:  true,
		EnableRequestID: true,
		EnableLogging:   true,
		EnableDB:        true,
		DBPool:          pool,
	}
	connectOpt := connectserver.NewConnectOption(mwCfg)

	mux := http.NewServeMux()
	path, sensorHandler := sensorv1connect.NewSensorServiceHandler(handler,
		connect.WithInterceptors(
			interceptors.RequestIDInterceptor(),
			interceptors.LoggingInterceptor(interceptors.WithLogger(p9log.NewHelper(logger))),
		),
		connectOpt,
	)
	mux.Handle(path, sensorHandler)

	mux.HandleFunc("/health", func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"ok"}`))
	})
	mux.HandleFunc("/ready", func(w http.ResponseWriter, _ *http.Request) {
		if err := pool.Ping(context.Background()); err != nil {
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"ready"}`))
	})

	serverCfg := connectserver.DefaultServerConfig(port)
	srv := connectserver.NewHTTPServer(serverCfg, mux)

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		p9log.NewHelper(logger).Infow("msg", "sensor-service starting", "port", port)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("server error: %v", err)
		}
	}()

	<-quit
	p9log.NewHelper(logger).Infow("msg", "shutting down sensor-service")

	shutCtx, shutCancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer shutCancel()
	if err := srv.Shutdown(shutCtx); err != nil {
		log.Printf("graceful shutdown error: %v", err)
	}
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}
